        } catch (Exception e) {
            server.disconnectedClient(this);
        }
    }

    // ── Fermeture ──────────────────────────────────────────────────────

    public void closeClient() {
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            socket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
