package org.example.leprojet.server;

import org.example.leprojet.MoveCalculator;
import org.example.leprojet.Arbitre;
import org.example.leprojet.core.Case;
import org.example.leprojet.core.Piece;
import org.example.leprojet.core.Plateau;
import org.example.leprojet.core.Couleur;
import org.example.leprojet.core.EtatPartie;
import org.example.leprojet.common.Message;
import org.example.leprojet.common.MessageType;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/**
 * Serveur de jeu de dames.
 * <ul>
 *   <li>Accepte 2 clients, leur assigne NOIR et BLANC.</li>
 *   <li>Héberge l'arbitre qui valide chaque coup.</li>
 *   <li>Broadcast les coups validés aux 2 clients.</li>
 * </ul>
 */
public class Server {

    private final int port;
    private final List<ConnectedClient> clients;
    private Arbitre arb;

    /**
     * Cree un serveur de jeu et demarre le thread d'ecoute des connexions.
     *
     * @param port port TCP d'ecoute
     * @throws IOException si la socket serveur ne peut pas etre creee
     */
    public Server(int port) throws IOException {
        this.port = port;
        this.clients = new ArrayList<>();
        new Thread(new Connection(this)).start();
        System.out.println("[SERVEUR] Démarré sur le port " + port);
    }

    /**
     * @return port TCP d'ecoute du serveur
     */
    public int getPort() { return port; }

    // ── Connexion d'un client ──────────────────────────────────────────

    /**
     * Ajoute un client connecte, assigne sa couleur et demarre la partie a 2 joueurs.
     *
     * @param newClient client nouvellement connecte
     */
    public synchronized void addClient(ConnectedClient newClient) {
        if (clients.size() >= 2) {
            newClient.sendMessage(new Message("Serveur", "Partie déjà pleine."));
            newClient.closeClient();
            return;
        }

        clients.add(newClient);

        // Assigner la couleur : 1er = NOIR, 2e = BLANC
        String couleur = (clients.size() == 1) ? "NOIR" : "BLANC";
        newClient.setCouleur(couleur);
        newClient.sendMessage(Message.assignationCouleur(couleur));
        System.out.println("[SERVEUR] Client " + newClient.getId() + " → " + couleur);

        // Quand 2 joueurs sont connectés → démarrer la partie
        if (clients.size() == 2) {
            demarrerPartie();
        }
    }

    // ── Démarrage de la partie ─────────────────────────────────────────

    private void demarrerPartie() {
        arb = new Arbitre("BLANC", "NOIR");
        arb.initialiserPartie();

        broadcastToAll(Message.debutPartie());
        System.out.println("[SERVEUR] Partie démarrée ! " + arb);
    }

    // ── Réception d'un message d'un client ─────────────────────────────

    /**
     * Route un message recu vers le traitement metier adapte.
     *
     * @param sender client emetteur
     * @param mess message recu
     */
    public synchronized void onMessageRecu(ConnectedClient sender, Message mess) {
        System.out.println("[SERVEUR][DISPATCH] client=" + sender.getId() + " type=" + mess.getType());
        switch (mess.getType()) {
            case COUP -> traiterCoup(sender, mess);
            case ABANDON -> traiterAbandon(sender, mess);
            case TEXTE -> traiterTexte(sender, mess);
            default -> {
                mess.setSender(String.valueOf(sender.getId()));
                broadcastToAll(mess);
            }
        }
    }

    private void traiterTexte(ConnectedClient sender, Message mess) {
        String brut = mess.getContent() == null ? "" : mess.getContent();
        String nettoye = brut.replaceAll("[\\p{Cntrl}&&[^\\r\\n\\t]]", "").trim();
        if (nettoye.isBlank() || nettoye.length() > 300) {
            sender.sendMessage(new Message("Serveur", "Message chat invalide (1..300 caractères requis)."));
            return;
        }

        String horodatage = java.time.LocalTime.now().withNano(0).toString();
        Message diffusion = Message.texte(String.valueOf(sender.getId()), "[" + horodatage + "] " + nettoye);
        diffusion.setTimestamp(System.currentTimeMillis());
        broadcastToAll(diffusion);
    }

    private void traiterAbandon(ConnectedClient sender, Message mess) {
        if (arb != null && arb.getEtat() == EtatPartie.EN_COURS) {
            Couleur couleurAbandonne = "BLANC".equals(sender.getCouleur()) ? Couleur.BLANC : Couleur.NOIR;
            arb.abandonner(couleurAbandonne);
        }
        String gagnant = "BLANC".equals(sender.getCouleur()) ? "NOIR" : "BLANC";
        System.out.println("[SERVEUR] Abandon reçu du client " + sender.getId() + " -> gagnant=" + gagnant);
        broadcastToAll(Message.finPartie(gagnant));
        broadcastToAll(new Message("Serveur", "Le joueur " + sender.getId() + " a abandonné."));
    }

    // ── Traitement d'un coup ───────────────────────────────────────────

    private void traiterCoup(ConnectedClient sender, Message mess) {
        if (arb == null) {
            sender.sendMessage(new Message(MessageType.COUP_INVALIDE, "Serveur", "Partie non démarrée."));
            return;
        }

        // Vérifier que c'est le tour de ce client
        String tourCouleur = arb.getJoueurCourant().getCouleur().toString();
        if (!tourCouleur.equals(sender.getCouleur())) {
            sender.sendMessage(new Message(MessageType.COUP_INVALIDE, "Serveur", "Ce n'est pas votre tour."));
            return;
        }

        Plateau plateau = arb.getPlateau();
        Case[][] cases = plateau.getCases();

        int lDep = mess.getLigneDepart();
        int cDep = mess.getColonneDepart();
        int lArr = mess.getLigneArrivee();
        int cArr = mess.getColonneArrivee();

        Case caseDepart = cases[lDep][cDep];
        Case caseArrivee = cases[lArr][cArr];
        Piece piece = caseDepart.getPiece();

        if (piece == null) {
            sender.sendMessage(new Message(MessageType.COUP_INVALIDE, "Serveur", "Pas de pièce en départ."));
            return;
        }

        boolean ok = false;

        // Tenter une prise (utilise MoveCalculator pour supporter pions ET dames)
        Piece piecePrise = MoveCalculator.trouverPiecePrise(piece, caseArrivee, plateau);
        if (piecePrise != null) {
            ok = arb.jouerPrise(piece, piecePrise, caseArrivee);
        }

        // Sinon déplacement simple
        if (!ok) {
            ok = arb.jouerDeplacement(piece, caseArrivee);
        }

        if (ok) {
            Message coupOk = Message.coupValide(lDep, cDep, lArr, cArr);
            broadcastToAll(coupOk);
            System.out.println("[SERVEUR][MOUVEMENT] dep=(" + lDep + "," + cDep + ") arr=(" + lArr + "," + cArr + ")");
            System.out.println("[SERVEUR] Coup validé : " + coupOk + " | " + arb);

            // Vérifier fin de partie
            if (arb.getGagnant() != null) {
                broadcastToAll(Message.finPartie(arb.getGagnant().getCouleur().toString()));
                System.out.println("[SERVEUR] Partie terminée ! Gagnant : " + arb.getGagnant());
            }
        } else {
            sender.sendMessage(new Message(MessageType.COUP_INVALIDE, "Serveur", "Coup invalide."));
        }
    }

    // ── Broadcast ──────────────────────────────────────────────────────

    /**
     * Diffuse un message a tous les clients connectes.
     *
     * @param mess message a diffuser
     */
    public synchronized void broadcastToAll(Message mess) {
        for (ConnectedClient client : clients) {
            client.sendMessage(mess);
        }
    }

    // ── Déconnexion ────────────────────────────────────────────────────

    /**
     * Supprime un client deconnecte et notifie les autres clients.
     *
     * @param discClient client deconnecte
     */
    public synchronized void disconnectedClient(ConnectedClient discClient) {
        discClient.closeClient();
        clients.remove(discClient);
        broadcastToAll(new Message("Serveur", "Le client " + discClient.getId() + " s'est déconnecté."));
        System.out.println("[SERVEUR] Client " + discClient.getId() + " déconnecté.");
    }
}

package org.example.leprojet.server;

import org.example.leprojet.MoveCalculator;
import org.example.leprojet.Arbitre;
import org.example.leprojet.core.Case;
import org.example.leprojet.core.Piece;
import org.example.leprojet.core.Plateau;
import org.example.leprojet.core.Couleur;
import org.example.leprojet.core.EtatPartie;
import org.example.leprojet.common.Message;
import org.example.leprojet.common.MessageType;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/**
 * Serveur de jeu de dames.
 * <ul>
 *   <li>Accepte 2 clients, leur assigne NOIR et BLANC.</li>
 *   <li>Héberge l'arbitre qui valide chaque coup.</li>
 *   <li>Broadcast les coups validés aux 2 clients.</li>
 * </ul>
 */
public class Server {

    private final int port;
    private final List<ConnectedClient> clients;
    private Arbitre arb;
    private boolean partieDemarree;

    /**
     * Cree un serveur de jeu et demarre le thread d'ecoute des connexions.
     *
     * @param port port TCP d'ecoute
     * @throws IOException si la socket serveur ne peut pas etre creee
     */
    public Server(int port) throws IOException {
        this.port = port;
        this.clients = new ArrayList<>();
        this.partieDemarree = false;
        new Thread(new Connection(this)).start();
        System.out.println("[SERVEUR] Démarré sur le port " + port);
    }

    /**
     * @return port TCP d'ecoute du serveur
     */
    public int getPort() { return port; }

    // ── Connexion d'un client ──────────────────────────────────────────

    /**
     * Ajoute un client connecte, assigne sa couleur et demarre la partie a 2 joueurs.
     *
     * @param newClient client nouvellement connecte
     */
    public synchronized void addClient(ConnectedClient newClient) {
        if (clients.size() >= 2) {
            newClient.sendMessage(new Message("Serveur", "Partie déjà pleine."));
            newClient.closeClient();
            return;
        }

        clients.add(newClient);

        // Assigner la couleur : 1er = NOIR, 2e = BLANC
        String couleur = (clients.size() == 1) ? "NOIR" : "BLANC";
        newClient.setCouleur(couleur);
        newClient.sendMessage(Message.assignationCouleur(couleur));
        System.out.println("[SERVEUR] Client " + newClient.getId() + " → " + couleur);

        essayerDemarrerPartie();
    }

    // ── Démarrage de la partie ─────────────────────────────────────────

    private void demarrerPartie() {
        ConnectedClient blanc = trouverParCouleur("BLANC");
        ConnectedClient noir = trouverParCouleur("NOIR");
        String nomBlanc = (blanc == null) ? "BLANC" : blanc.getPseudoAffiche();
        String nomNoir = (noir == null) ? "NOIR" : noir.getPseudoAffiche();

        arb = new Arbitre(nomBlanc, nomNoir);
        arb.initialiserPartie();
        partieDemarree = true;

        diffuserInfosJoueurs();
        broadcastToAll(Message.debutPartie());
        System.out.println("[SERVEUR] Partie démarrée ! " + arb);
    }

    private void essayerDemarrerPartie() {
        if (partieDemarree || clients.size() != 2) return;
        if (!clientsPrets()) return;
        demarrerPartie();
    }

    private boolean clientsPrets() {
        for (ConnectedClient c : clients) {
            if (!c.hasHelloPseudo()) {
                return false;
            }
        }
        return true;
    }

    private void diffuserInfosJoueurs() {
        ConnectedClient blanc = trouverParCouleur("BLANC");
        ConnectedClient noir = trouverParCouleur("NOIR");
        if (blanc == null || noir == null) return;

        Message infos = Message.infosJoueurs(blanc.getPseudoAffiche(), noir.getPseudoAffiche());
        broadcastToAll(infos);
    }

    private ConnectedClient trouverParCouleur(String couleur) {
        for (ConnectedClient client : clients) {
            if (couleur.equals(client.getCouleur())) {
                return client;
            }
        }
        return null;
    }

    // ── Réception d'un message d'un client ─────────────────────────────

    /**
     * Route un message recu vers le traitement metier adapte.
     *
     * @param sender client emetteur
     * @param mess message recu
     */
    public synchronized void onMessageRecu(ConnectedClient sender, Message mess) {
        System.out.println("[SERVEUR][DISPATCH] client=" + sender.getId() + " type=" + mess.getType());
        switch (mess.getType()) {
            case HELLO_PSEUDO -> traiterHelloPseudo(sender, mess);
            case COUP -> traiterCoup(sender, mess);
            case ABANDON -> traiterAbandon(sender, mess);
            case TEXTE -> traiterTexte(sender, mess);
            default -> {
                mess.setSender(sender.getPseudoAffiche());
                broadcastToAll(mess);
            }
        }
    }

    private void traiterHelloPseudo(ConnectedClient sender, Message mess) {
        String brut = mess.getContent() == null ? "" : mess.getContent();
        String pseudo = brut.replaceAll("[\\p{Cntrl}&&[^\\r\\n\\t]]", "").trim();
        if (pseudo.isBlank()) {
            sender.sendMessage(new Message("Serveur", "Pseudo invalide."));
            return;
        }
        if (pseudo.length() > 24) {
            pseudo = pseudo.substring(0, 24);
        }

        sender.setPseudo(pseudo);
        diffuserInfosJoueurs();
        essayerDemarrerPartie();
    }

    private void traiterTexte(ConnectedClient sender, Message mess) {
        String brut = mess.getContent() == null ? "" : mess.getContent();
        String nettoye = brut.replaceAll("[\\p{Cntrl}&&[^\\r\\n\\t]]", "").trim();
        if (nettoye.isBlank() || nettoye.length() > 300) {
            sender.sendMessage(new Message("Serveur", "Message chat invalide (1..300 caractères requis)."));
            return;
        }

        String horodatage = java.time.LocalTime.now().withNano(0).toString();
        Message diffusion = Message.texte(sender.getPseudoAffiche(), "[" + horodatage + "] " + nettoye);
        diffusion.setTimestamp(System.currentTimeMillis());
        broadcastToAll(diffusion);
    }

    private void traiterAbandon(ConnectedClient sender, Message mess) {
        if (arb != null && arb.getEtat() == EtatPartie.EN_COURS) {
            Couleur couleurAbandonne = "BLANC".equals(sender.getCouleur()) ? Couleur.BLANC : Couleur.NOIR;
            arb.abandonner(couleurAbandonne);
        }
        String gagnant = "BLANC".equals(sender.getCouleur()) ? "NOIR" : "BLANC";
        System.out.println("[SERVEUR] Abandon reçu du client " + sender.getPseudoAffiche() + " -> gagnant=" + gagnant);
        broadcastToAll(Message.finPartie(gagnant));
        broadcastToAll(new Message("Serveur", "Le joueur " + sender.getPseudoAffiche() + " a abandonné."));
    }

    // ── Traitement d'un coup ───────────────────────────────────────────

    private void traiterCoup(ConnectedClient sender, Message mess) {
        if (arb == null) {
            sender.sendMessage(new Message(MessageType.COUP_INVALIDE, "Serveur", "Partie non démarrée."));
            return;
        }

        // Vérifier que c'est le tour de ce client
        String tourCouleur = arb.getJoueurCourant().getCouleur().toString();
        if (!tourCouleur.equals(sender.getCouleur())) {
            sender.sendMessage(new Message(MessageType.COUP_INVALIDE, "Serveur", "Ce n'est pas votre tour."));
            return;
        }

        Plateau plateau = arb.getPlateau();
        Case[][] cases = plateau.getCases();

        int lDep = mess.getLigneDepart();
        int cDep = mess.getColonneDepart();
        int lArr = mess.getLigneArrivee();
        int cArr = mess.getColonneArrivee();

        Case caseDepart = cases[lDep][cDep];
        Case caseArrivee = cases[lArr][cArr];
        Piece piece = caseDepart.getPiece();

        if (piece == null) {
            sender.sendMessage(new Message(MessageType.COUP_INVALIDE, "Serveur", "Pas de pièce en départ."));
            return;
        }

        boolean ok = false;

        // Tenter une prise (utilise MoveCalculator pour supporter pions ET dames)
        Piece piecePrise = MoveCalculator.trouverPiecePrise(piece, caseArrivee, plateau);
        if (piecePrise != null) {
            ok = arb.jouerPrise(piece, piecePrise, caseArrivee);
        }

        // Sinon déplacement simple
        if (!ok) {
            ok = arb.jouerDeplacement(piece, caseArrivee);
        }

        if (ok) {
            Message coupOk = Message.coupValide(lDep, cDep, lArr, cArr);
            broadcastToAll(coupOk);
            System.out.println("[SERVEUR][MOUVEMENT] dep=(" + lDep + "," + cDep + ") arr=(" + lArr + "," + cArr + ")");
            System.out.println("[SERVEUR] Coup validé : " + coupOk + " | " + arb);

            // Vérifier fin de partie
            if (arb.getGagnant() != null) {
                broadcastToAll(Message.finPartie(arb.getGagnant().getCouleur().toString()));
                System.out.println("[SERVEUR] Partie terminée ! Gagnant : " + arb.getGagnant());
            }
        } else {
            sender.sendMessage(new Message(MessageType.COUP_INVALIDE, "Serveur", "Coup invalide."));
        }
    }

    // ── Broadcast ──────────────────────────────────────────────────────

    /**
     * Diffuse un message a tous les clients connectes.
     *
     * @param mess message a diffuser
     */
    public synchronized void broadcastToAll(Message mess) {
        for (ConnectedClient client : clients) {
            client.sendMessage(mess);
        }
    }

    // ── Déconnexion ────────────────────────────────────────────────────

    /**
     * Supprime un client deconnecte et notifie les autres clients.
     *
     * @param discClient client deconnecte
     */
    public synchronized void disconnectedClient(ConnectedClient discClient) {
        discClient.closeClient();
        clients.remove(discClient);
        partieDemarree = false;
        broadcastToAll(new Message("Serveur", "Le joueur " + discClient.getPseudoAffiche() + " s'est déconnecté."));
        System.out.println("[SERVEUR] Client " + discClient.getPseudoAffiche() + " déconnecté.");
    }
}

package org.example.leprojet.ui;

import org.example.leprojet.core.Case;
import org.example.leprojet.core.Couleur;
import org.example.leprojet.core.Dame;
import org.example.leprojet.core.Piece;

import javafx.scene.Node;
import javafx.scene.control.Label;
import javafx.scene.effect.DropShadow;
import javafx.scene.effect.InnerShadow;
import javafx.scene.layout.StackPane;
import javafx.scene.paint.Color;
import javafx.scene.paint.CycleMethod;
import javafx.scene.paint.RadialGradient;
import javafx.scene.paint.Stop;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Rectangle;
import javafx.scene.text.Font;
import javafx.scene.text.FontWeight;

/**
 * Rendu graphique d'une case et d'une pièce du damier.
 * <p>
 * Style esthétique inspiré de chess.com / lichess :
 * pièces avec dégradés, ombres portées, couronne pour les dames.
 */
public class CaseRenderer {

    /** Taille d'une case en pixels. */
    public static final double TAILLE_CASE = 54;

    private CaseRenderer() {
    }

    // ── Couleurs du thème ──────────────────────────────────────────────

    private static final Color CASE_FONCEE = Color.web("#b58863");
    private static final Color CASE_CLAIRE = Color.web("#f0d9b5");

    private static final Color SELECTION_FILL = Color.web("#f6f669", 0.75);
    private static final Color DESTINATION_FILL = Color.web("#829769", 0.45);

    // Pièces
    private static final Color PIECE_NOIRE_CENTRE = Color.web("#3d3d3d");
    private static final Color PIECE_NOIRE_BORD = Color.web("#1a1a1a");
    private static final Color PIECE_BLANCHE_CENTRE = Color.web("#ffffff");
    private static final Color PIECE_BLANCHE_BORD = Color.web("#d4d4d4");

    private static final Color CONTOUR_PIECE_NOIRE = Color.web("#8b7355");
    private static final Color CONTOUR_PIECE_BLANCHE = Color.web("#6b5a3e");

    // ── Rendu d'une case ───────────────────────────────────────────────

    /**
     * Crée le nœud graphique d'une case du damier.
     */
    public static StackPane creerCaseNode(Case cs, boolean selected, boolean isDest) {
        Rectangle fond = new Rectangle(TAILLE_CASE, TAILLE_CASE);
        fond.setArcWidth(0);
        fond.setArcHeight(0);

        // Couleur de fond
        Color baseCouleur = cs.getCouleur() == Couleur.NOIR ? CASE_FONCEE : CASE_CLAIRE;
        fond.setFill(baseCouleur);

        StackPane cell = new StackPane(fond);

        // Surbrillance sélection
        if (selected) {
            Rectangle highlight = new Rectangle(TAILLE_CASE, TAILLE_CASE);
            highlight.setFill(SELECTION_FILL);
            cell.getChildren().add(highlight);
        }

        // Pièce sur la case
        Piece piece = cs.getPiece();
        if (piece != null) {
            cell.getChildren().add(creerNoeudPiece(piece));
        }

        // Indicateur de destination (point ou cercle)
        if (isDest) {
            if (cs.estVide()) {
                // Point de destination semi-transparent
                Circle dot = new Circle(TAILLE_CASE * 0.14);
                dot.setFill(DESTINATION_FILL);
                cell.getChildren().add(dot);
            } else {
                // Cercle autour de la pièce capturable
                Circle ring = new Circle(TAILLE_CASE * 0.44);
                ring.setFill(Color.TRANSPARENT);
                ring.setStroke(DESTINATION_FILL);
                ring.setStrokeWidth(TAILLE_CASE * 0.08);
                cell.getChildren().add(ring);
            }
        }

        return cell;
    }

    // ── Rendu d'une pièce ──────────────────────────────────────────────

    /**
     * Crée le nœud graphique d'une pièce (pion ou dame) avec dégradé et ombre.
     */
    public static Node creerNoeudPiece(Piece piece) {
        boolean noir = piece.getCouleur() == Couleur.NOIR;
        double rayon = TAILLE_CASE * 0.37;

        // Cercle principal avec dégradé radial
        Circle cercle = new Circle(rayon);
        RadialGradient gradient = new RadialGradient(
                0, 0, 0.35, 0.35, 0.8, true, CycleMethod.NO_CYCLE,
                new Stop(0, noir ? PIECE_NOIRE_CENTRE : PIECE_BLANCHE_CENTRE),
                new Stop(1, noir ? PIECE_NOIRE_BORD : PIECE_BLANCHE_BORD)
        );
        cercle.setFill(gradient);

        // Contour
        cercle.setStroke(noir ? CONTOUR_PIECE_NOIRE : CONTOUR_PIECE_BLANCHE);
        cercle.setStrokeWidth(2.2);

        // Ombre portée
        DropShadow ombre = new DropShadow();
        ombre.setRadius(4);
        ombre.setOffsetX(1.5);
        ombre.setOffsetY(2.5);
        ombre.setColor(Color.web("#000000", 0.35));
        cercle.setEffect(ombre);

        StackPane sp = new StackPane(cercle);

        // Dame : couronne dorée ♛
        if (piece instanceof Dame) {
            Label crown = new Label("♛");
            crown.setFont(Font.font("System", FontWeight.BOLD, rayon * 1.1));
            crown.setTextFill(noir ? Color.web("#ffd700") : Color.web("#c8a415"));

            // Ombre interne sur le texte
            InnerShadow innerShadow = new InnerShadow();
            innerShadow.setRadius(2);
            innerShadow.setColor(Color.web("#000000", 0.3));
            crown.setEffect(innerShadow);

            sp.getChildren().add(crown);
        }

        return sp;
    }

    // ── Couleur de fond d'une case ─────────────────────────────────────

    /**
     * Retourne la couleur de fond d'une case.
     */
    public static Color couleurFond(Case cs) {
        return cs.getCouleur() == Couleur.NOIR ? CASE_FONCEE : CASE_CLAIRE;
    }
}

package org.example.leprojet.ui;

import org.example.leprojet.core.Case;
import org.example.leprojet.core.Couleur;
import org.example.leprojet.core.Dame;
import org.example.leprojet.core.Piece;

import javafx.scene.Node;
import javafx.scene.control.Label;
import javafx.scene.effect.DropShadow;
import javafx.scene.effect.InnerShadow;
import javafx.scene.layout.StackPane;
import javafx.scene.paint.Color;
import javafx.scene.paint.CycleMethod;
import javafx.scene.paint.RadialGradient;
import javafx.scene.paint.Stop;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Rectangle;
import javafx.scene.text.Font;
import javafx.scene.text.FontWeight;

/**
 * Rendu graphique d'une case et d'une pièce du damier.
 * <p>
 * Style esthétique inspiré de chess.com / lichess :
 * pièces avec dégradés, ombres portées, couronne pour les dames.
 */
public class CaseRenderer {

    /** Taille d'une case en pixels. */
    public static final double TAILLE_CASE = 54;

    private CaseRenderer() {
    }

    // ── Couleurs du thème ──────────────────────────────────────────────

    private static final Color CASE_FONCEE = Color.web("#b58863");
    private static final Color CASE_CLAIRE = Color.web("#f0d9b5");

    private static final Color SELECTION_FILL = Color.web("#f6f669", 0.75);
    private static final Color DESTINATION_FILL = Color.web("#829769", 0.45);

    // Pièces
    private static final Color PIECE_NOIRE_CENTRE = Color.web("#3d3d3d");
    private static final Color PIECE_NOIRE_BORD = Color.web("#1a1a1a");
    private static final Color PIECE_BLANCHE_CENTRE = Color.web("#ffffff");
    private static final Color PIECE_BLANCHE_BORD = Color.web("#d4d4d4");

    private static final Color CONTOUR_PIECE_NOIRE = Color.web("#8b7355");
    private static final Color CONTOUR_PIECE_BLANCHE = Color.web("#6b5a3e");

    // ── Rendu d'une case ───────────────────────────────────────────────

    /**
     * Crée le nœud graphique d'une case du damier.
     */
    public static StackPane creerCaseNode(Case cs, boolean selected, boolean isDest, boolean isCaptureDest) {
        Rectangle fond = new Rectangle(TAILLE_CASE, TAILLE_CASE);
        fond.setArcWidth(0);
        fond.setArcHeight(0);

        // Couleur de fond
        Color baseCouleur = cs.getCouleur() == Couleur.NOIR ? CASE_FONCEE : CASE_CLAIRE;
        fond.setFill(baseCouleur);

        StackPane cell = new StackPane(fond);
        cell.getStyleClass().add("board-cell");

        // Surbrillance sélection
        if (selected) {
            Rectangle highlight = new Rectangle(TAILLE_CASE, TAILLE_CASE);
            highlight.setFill(SELECTION_FILL);
            cell.getChildren().add(highlight);
            cell.getStyleClass().add("cell-selected");
        }

        // Pièce sur la case
        Piece piece = cs.getPiece();
        if (piece != null) {
            cell.getChildren().add(creerNoeudPiece(piece));
        }

        // Indicateur de destination (point ou cercle)
        if (isDest) {
            if (cs.estVide()) {
                // Point de destination semi-transparent
                Circle dot = new Circle(TAILLE_CASE * 0.14);
                dot.setFill(DESTINATION_FILL);
                DropShadow glow = new DropShadow();
                glow.setRadius(10);
                glow.setColor(Color.web("#b4d88a", 0.70));
                dot.setEffect(glow);
                cell.getStyleClass().add("cell-destination");
                cell.getChildren().add(dot);
            } else {
                // Cercle autour de la pièce capturable
                Circle ring = new Circle(TAILLE_CASE * 0.44);
                ring.setFill(Color.TRANSPARENT);
                ring.setStroke(DESTINATION_FILL);
                ring.setStrokeWidth(TAILLE_CASE * 0.08);
                DropShadow captureGlow = new DropShadow();
                captureGlow.setRadius(12);
                captureGlow.setColor(Color.web("#ff7043", 0.75));
                ring.setEffect(captureGlow);
                cell.getStyleClass().add("cell-capture-destination");
                cell.getChildren().add(ring);
            }
        }

        if (isCaptureDest) {
            cell.getStyleClass().add("cell-capture-destination");
        }

        return cell;
    }

    // ── Rendu d'une pièce ──────────────────────────────────────────────

    /**
     * Crée le nœud graphique d'une pièce (pion ou dame) avec dégradé et ombre.
     */
    public static Node creerNoeudPiece(Piece piece) {
        boolean noir = piece.getCouleur() == Couleur.NOIR;
        double rayon = TAILLE_CASE * 0.37;

        // Cercle principal avec dégradé radial
        Circle cercle = new Circle(rayon);
        RadialGradient gradient = new RadialGradient(
                0, 0, 0.35, 0.35, 0.8, true, CycleMethod.NO_CYCLE,
                new Stop(0, noir ? PIECE_NOIRE_CENTRE : PIECE_BLANCHE_CENTRE),
                new Stop(1, noir ? PIECE_NOIRE_BORD : PIECE_BLANCHE_BORD)
        );
        cercle.setFill(gradient);

        // Contour
        cercle.setStroke(noir ? CONTOUR_PIECE_NOIRE : CONTOUR_PIECE_BLANCHE);
        cercle.setStrokeWidth(2.2);

        // Ombre portée
        DropShadow ombre = new DropShadow();
        ombre.setRadius(4);
        ombre.setOffsetX(1.5);
        ombre.setOffsetY(2.5);
        ombre.setColor(Color.web("#000000", 0.35));
        cercle.setEffect(ombre);

        StackPane sp = new StackPane(cercle);

        // Dame : couronne dorée ♛
        if (piece instanceof Dame) {
            Label crown = new Label("♛");
            crown.setFont(Font.font("System", FontWeight.BOLD, rayon * 1.1));
            crown.setTextFill(noir ? Color.web("#ffd700") : Color.web("#c8a415"));

            // Ombre interne sur le texte
            InnerShadow innerShadow = new InnerShadow();
            innerShadow.setRadius(2);
            innerShadow.setColor(Color.web("#000000", 0.3));
            crown.setEffect(innerShadow);

            sp.getChildren().add(crown);
        }

        return sp;
    }

    // ── Couleur de fond d'une case ─────────────────────────────────────

    /**
     * Retourne la couleur de fond d'une case.
     */
    public static Color couleurFond(Case cs) {
        return cs.getCouleur() == Couleur.NOIR ? CASE_FONCEE : CASE_CLAIRE;
    }
}

package org.example.leprojet.ui;

import org.example.leprojet.Arbitre;
import org.example.leprojet.CoupCallback;
import org.example.leprojet.MoveCalculator;
import org.example.leprojet.core.Case;
import org.example.leprojet.core.Couleur;
import org.example.leprojet.core.EtatPartie;
import org.example.leprojet.core.Piece;
import org.example.leprojet.core.Plateau;
import org.example.leprojet.ui.SoundManager;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.layout.BorderPane;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.StackPane;

import java.util.ArrayList;
import java.util.List;

/**
 * Vue du damier 10×10.
 * <p>
 * Gère le rendu graphique (via {@link CaseRenderer}) et la sélection au clic.
 * Le coup est délégué à un {@link CoupCallback} (local ou réseau).
 */
public class DamierView extends BorderPane {

    private Plateau plateau;
    private final GridPane grille;
    private final Arbitre arb;
    private final Couleur couleurJoueur;

    private Piece pieceSelectionnee;
    private final List<Case> destinationsPossibles = new ArrayList<>();

    /** Callback coup (mode local ou réseau). */
    private CoupCallback coupCallback;

    /** Callback post-coup pour rafraîchir d'autres vues. */
    private Runnable onCoupJoue;

    // ─────────────────────────────────────────────────────────────────
    //  Constructeurs
    // ─────────────────────────────────────────────────────────────────

    public DamierView() {
        this(null, null, null);
    }

    public DamierView(Plateau plateau) {
        this(plateau, null, null);
    }

    public DamierView(Plateau plateau, Arbitre arb, Couleur couleurJoueur) {
        this.arb = arb;
        this.couleurJoueur = couleurJoueur;
        this.plateau = (plateau != null) ? plateau : creerPlateauParDefaut();

        this.grille = new GridPane();
        grille.setAlignment(Pos.CENTER);
        grille.setHgap(0);
        grille.setVgap(0);
        grille.setStyle("-fx-background-color: #3f2a1d; -fx-padding: 4;");

        dessinerGrille();

        setStyle("-fx-background-color: transparent;");
        setCenter(grille);
        setPadding(new Insets(4));
    }

    private Plateau creerPlateauParDefaut() {
        Plateau p = new Plateau();
        p.initPions();
        return p;
    }

    // ─────────────────────────────────────────────────────────────────
    //  Setters
    // ─────────────────────────────────────────────────────────────────

    public void setOnCoupJoue(Runnable r)        { this.onCoupJoue = r; }
    public void setCoupCallback(CoupCallback cb) { this.coupCallback = cb; }

    public void setPlateau(Plateau plateau) {
        this.plateau = plateau;
        rafraichir();
    }

    // ─────────────────────────────────────────────────────────────────
    //  Rafraîchissement
    // ─────────────────────────────────────────────────────────────────

    /** Efface la sélection et redessine. Auto-sélectionne en chaîne. */
    public void rafraichir() {
        pieceSelectionnee = null;
        destinationsPossibles.clear();
        autoSelectChaine();
        redessinGrille();
    }

    private void redessinGrille() {
        grille.getChildren().clear();
        dessinerGrille();
    }

    private void autoSelectChaine() {
        if (arb != null && arb.isEnChaineDePrise()
                && couleurJoueur != null
                && arb.getJoueurCourant().getCouleur() == couleurJoueur) {
            pieceSelectionnee = arb.getPieceEnChaine();
            calculerDestinations(pieceSelectionnee);
        }
    }

    // ─────────────────────────────────────────────────────────────────
    //  Dessin (délègue à CaseRenderer)
    // ─────────────────────────────────────────────────────────────────

    private void dessinerGrille() {
        Case[][] cases = plateau.getCases();
        for (int l = 0; l < Plateau.NB_LIGNES; l++) {
            for (int c = 0; c < Plateau.NB_COLONNES; c++) {
                Case cs = cases[l][c];
                boolean selected = pieceSelectionnee != null && pieceSelectionnee.getPosition() == cs;
                boolean isDest = destinationsPossibles.contains(cs);

                StackPane cell = CaseRenderer.creerCaseNode(cs, selected, isDest);
                cell.setOnMouseClicked(e -> onClic(cs));
                grille.add(cell, c, l);
            }
        }
    }

    // ─────────────────────────────────────────────────────────────────
    //  Destinations possibles
    // ─────────────────────────────────────────────────────────────────

    private void calculerDestinations(Piece piece) {
        destinationsPossibles.clear();
        if (arb == null || piece == null) return;

        if (arb.isEnChaineDePrise()) {
            destinationsPossibles.addAll(arb.getPrisesPossiblesPour(piece));
            return;
        }

        if (arb.joueurCourantAPrisePossible()) {
            destinationsPossibles.addAll(arb.getPrisesPossiblesPour(piece));
        } else {
            destinationsPossibles.addAll(
                    MoveCalculator.getDeplacementsPossibles(piece, plateau));
        }
    }

    // ─────────────────────────────────────────────────────────────────
    //  Logique de clic
    // ─────────────────────────────────────────────────────────────────

    private void onClic(Case cs) {
        if (arb == null || arb.getEtat() != EtatPartie.EN_COURS) return;
        if (couleurJoueur != null && arb.getJoueurCourant().getCouleur() != couleurJoueur) return;

        // Chaîne de prises
        if (arb.isEnChaineDePrise()) {
            gererClicChaine(cs);
            return;
        }

        // Sélection / jeu normal
        if (pieceSelectionnee == null) {
            selectionnerPiece(cs);
        } else {
            jouerOuReselectionner(cs);
        }
    }

    private void selectionnerPiece(Case cs) {
        Piece p = cs.getPiece();
        if (p == null || p.getCouleur() != couleurJoueur) return;
        if (arb.joueurCourantAPrisePossible() && arb.getPrisesPossiblesPour(p).isEmpty()) return;

        pieceSelectionnee = p;
        calculerDestinations(p);
        redessinGrille();
    }

    private void jouerOuReselectionner(Case cs) {
        // Re-sélection d'une autre de ses pièces
        if (cs.getPiece() != null && cs.getPiece().getCouleur() == couleurJoueur) {
            Piece p = cs.getPiece();
            if (arb.joueurCourantAPrisePossible() && arb.getPrisesPossiblesPour(p).isEmpty()) return;
            pieceSelectionnee = p;
            calculerDestinations(p);
            redessinGrille();
            return;
        }

        // Tenter le coup
        int lDep = pieceSelectionnee.getPosition().getLigne();
        int cDep = pieceSelectionnee.getPosition().getColonne();
        boolean ok = tenteCoup(pieceSelectionnee, cs);

        if (ok) {
            envoyerCoup(lDep, cDep, cs.getLigne(), cs.getColonne());
            apresCoupe();
        } else {
            pieceSelectionnee = null;
            destinationsPossibles.clear();
            redessinGrille();
        }
    }

    private void gererClicChaine(Case cs) {
        Piece chain = arb.getPieceEnChaine();
        if (!cs.estVide() || !destinationsPossibles.contains(cs)) return;

        int lDep = chain.getPosition().getLigne();
        int cDep = chain.getPosition().getColonne();

        // Trouver la pièce prise sur le chemin (pion ou dame)
        Piece milieu = MoveCalculator.trouverPiecePrise(chain, cs, plateau);
        if (milieu == null) return;

        boolean ok = arb.jouerPrise(chain, milieu, cs);
        if (ok) {
            SoundManager.playCapture();
            envoyerCoup(lDep, cDep, cs.getLigne(), cs.getColonne());
            apresCoupe();
        }
    }

    // ─────────────────────────────────────────────────────────────────
    //  Exécution du coup via l'arbitre
    // ─────────────────────────────────────────────────────────────────

    private boolean tenteCoup(Piece piece, Case dest) {
        // Tenter une prise
        Piece piecePrise = MoveCalculator.trouverPiecePrise(piece, dest, plateau);
        if (piecePrise != null) {
            boolean ok = arb.jouerPrise(piece, piecePrise, dest);
            if (ok) {
                SoundManager.playCapture();
                return true;
            }
        }

        // Sinon déplacement simple
        boolean ok = arb.jouerDeplacement(piece, dest);
        if (ok) {
            SoundManager.playMove();
        }
        return ok;
    }

    private void envoyerCoup(int lDep, int cDep, int lArr, int cArr) {
        if (coupCallback != null) {
            coupCallback.onCoup(lDep, cDep, lArr, cArr);
        }
    }

    /**
     * Après un coup validé : rafraîchir la grille DANS TOUS LES CAS,
     * gérer la chaîne de prises, et notifier le callback.
     */
    private void apresCoupe() {
        if (arb.isEnChaineDePrise()) {
            pieceSelectionnee = arb.getPieceEnChaine();
            calculerDestinations(pieceSelectionnee);
        } else {
            pieceSelectionnee = null;
            destinationsPossibles.clear();
        }

        // ★ FIX : toujours redessiner la grille après un coup
        redessinGrille();

        // Vérifier fin de partie
        if (arb.getGagnant() != null) {
            SoundManager.playVictory();
        }

        if (onCoupJoue != null) onCoupJoue.run();
    }
}

package org.example.leprojet.ui;

import org.example.leprojet.Arbitre;
import org.example.leprojet.CoupCallback;
import org.example.leprojet.MoveCalculator;
import org.example.leprojet.core.Case;
import org.example.leprojet.core.Couleur;
import org.example.leprojet.core.EtatPartie;
import org.example.leprojet.core.Piece;
import org.example.leprojet.core.Plateau;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.layout.BorderPane;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.StackPane;

import java.util.ArrayList;
import java.util.List;

/**
 * Vue du damier 10×10.
 * <p>
 * Gère le rendu graphique (via {@link CaseRenderer}) et la sélection au clic.
 * Le coup est délégué à un {@link CoupCallback} (local ou réseau).
 */
public class DamierView extends BorderPane {

    public static final double TAILLE_DAMIER_PREF = Plateau.NB_COLONNES * CaseRenderer.TAILLE_CASE + 12;

    private Plateau plateau;
    private final GridPane grille;
    private final Arbitre arb;
    private final Couleur couleurJoueur;

    private Piece pieceSelectionnee;
    private final List<Case> destinationsPossibles = new ArrayList<>();

    /** Callback coup (mode local ou réseau). */
    private CoupCallback coupCallback;

    /** Callback post-coup pour rafraîchir d'autres vues. */
    private Runnable onCoupJoue;

    // ─────────────────────────────────────────────────────────────────
    //  Constructeurs
    // ─────────────────────────────────────────────────────────────────

    public DamierView() {
        this(null, null, null);
    }

    public DamierView(Plateau plateau) {
        this(plateau, null, null);
    }

    public DamierView(Plateau plateau, Arbitre arb, Couleur couleurJoueur) {
        this.arb = arb;
        this.couleurJoueur = couleurJoueur;
        this.plateau = (plateau != null) ? plateau : creerPlateauParDefaut();

        this.grille = new GridPane();
        grille.setAlignment(Pos.CENTER);
        grille.setHgap(0);
        grille.setVgap(0);
        grille.setStyle("-fx-background-color: #3f2a1d; -fx-padding: 4;");
        setMinSize(TAILLE_DAMIER_PREF, TAILLE_DAMIER_PREF);
        setPrefSize(TAILLE_DAMIER_PREF, TAILLE_DAMIER_PREF);

        dessinerGrille();

        setStyle("-fx-background-color: transparent;");
        setCenter(grille);
        setPadding(new Insets(4));
    }

    private Plateau creerPlateauParDefaut() {
        Plateau p = new Plateau();
        p.initPions();
        return p;
    }

    // ─────────────────────────────────────────────────────────────────
    //  Setters
    // ─────────────────────────────────────────────────────────────────

    public void setOnCoupJoue(Runnable r)        { this.onCoupJoue = r; }
    public void setCoupCallback(CoupCallback cb) { this.coupCallback = cb; }

    public void setPlateau(Plateau plateau) {
        this.plateau = plateau;
        rafraichir();
    }

    // ─────────────────────────────────────────────────────────────────
    //  Rafraîchissement
    // ─────────────────────────────────────────────────────────────────

    /** Efface la sélection et redessine. Auto-sélectionne en chaîne. */
    public void rafraichir() {
        pieceSelectionnee = null;
        destinationsPossibles.clear();
        autoSelectChaine();
        redessinGrille();
    }

    private void redessinGrille() {
        grille.getChildren().clear();
        dessinerGrille();
    }

    private void autoSelectChaine() {
        if (arb != null && arb.isEnChaineDePrise()
                && couleurJoueur != null
                && arb.getJoueurCourant().getCouleur() == couleurJoueur) {
            pieceSelectionnee = arb.getPieceEnChaine();
            calculerDestinations(pieceSelectionnee);
        }
    }

    // ─────────────────────────────────────────────────────────────────
    //  Dessin (délègue à CaseRenderer)
    // ─────────────────────────────────────────────────────────────────

    private void dessinerGrille() {
        Case[][] cases = plateau.getCases();
        for (int l = 0; l < Plateau.NB_LIGNES; l++) {
            for (int c = 0; c < Plateau.NB_COLONNES; c++) {
                Case cs = cases[l][c];
                boolean selected = pieceSelectionnee != null && pieceSelectionnee.getPosition() == cs;
                boolean isDest = destinationsPossibles.contains(cs);
                boolean isCaptureDest = isDest && !cs.estVide();

                StackPane cell = CaseRenderer.creerCaseNode(cs, selected, isDest, isCaptureDest);
                cell.setOnMouseClicked(e -> onClic(cs));
                grille.add(cell, c, l);
            }
        }
    }

    // ─────────────────────────────────────────────────────────────────
    //  Destinations possibles
    // ─────────────────────────────────────────────────────────────────

    private void calculerDestinations(Piece piece) {
        destinationsPossibles.clear();
        if (arb == null || piece == null) return;

        if (arb.isEnChaineDePrise()) {
            destinationsPossibles.addAll(arb.getPrisesPossiblesPour(piece));
            return;
        }

        if (arb.joueurCourantAPrisePossible()) {
            destinationsPossibles.addAll(arb.getPrisesPossiblesPour(piece));
        } else {
            destinationsPossibles.addAll(
                    MoveCalculator.getDeplacementsPossibles(piece, plateau));
        }
    }

    // ─────────────────────────────────────────────────────────────────
    //  Logique de clic
    // ─────────────────────────────────────────────────────────────────

    private void onClic(Case cs) {
        if (arb == null || arb.getEtat() != EtatPartie.EN_COURS) return;
        if (couleurJoueur != null && arb.getJoueurCourant().getCouleur() != couleurJoueur) return;

        // Chaîne de prises
        if (arb.isEnChaineDePrise()) {
            gererClicChaine(cs);
            return;
        }

        // Sélection / jeu normal
        if (pieceSelectionnee == null) {
            selectionnerPiece(cs);
        } else {
            jouerOuReselectionner(cs);
        }
    }

    private void selectionnerPiece(Case cs) {
        Piece p = cs.getPiece();
        if (p == null || p.getCouleur() != couleurJoueur) return;
        if (arb.joueurCourantAPrisePossible() && arb.getPrisesPossiblesPour(p).isEmpty()) return;

        pieceSelectionnee = p;
        calculerDestinations(p);
        redessinGrille();
    }

    private void jouerOuReselectionner(Case cs) {
        // Re-sélection d'une autre de ses pièces
        if (cs.getPiece() != null && cs.getPiece().getCouleur() == couleurJoueur) {
            Piece p = cs.getPiece();
            if (arb.joueurCourantAPrisePossible() && arb.getPrisesPossiblesPour(p).isEmpty()) return;
            pieceSelectionnee = p;
            calculerDestinations(p);
            redessinGrille();
            return;
        }

        // Tenter le coup
        int lDep = pieceSelectionnee.getPosition().getLigne();
        int cDep = pieceSelectionnee.getPosition().getColonne();
        boolean ok = tenteCoup(pieceSelectionnee, cs);

        if (ok) {
            envoyerCoup(lDep, cDep, cs.getLigne(), cs.getColonne());
            apresCoupe();
        } else {
            pieceSelectionnee = null;
            destinationsPossibles.clear();
            redessinGrille();
        }
    }

    private void gererClicChaine(Case cs) {
        Piece chain = arb.getPieceEnChaine();
        if (!cs.estVide() || !destinationsPossibles.contains(cs)) return;

        int lDep = chain.getPosition().getLigne();
        int cDep = chain.getPosition().getColonne();

        // Trouver la pièce prise sur le chemin (pion ou dame)
        Piece milieu = MoveCalculator.trouverPiecePrise(chain, cs, plateau);
        if (milieu == null) return;

        boolean ok = arb.jouerPrise(chain, milieu, cs);
        if (ok) {
            SoundManager.playCapture();
            envoyerCoup(lDep, cDep, cs.getLigne(), cs.getColonne());
            apresCoupe();
        }
    }

    // ─────────────────────────────────────────────────────────────────
    //  Exécution du coup via l'arbitre
    // ─────────────────────────────────────────────────────────────────

    private boolean tenteCoup(Piece piece, Case dest) {
        // Tenter une prise
        Piece piecePrise = MoveCalculator.trouverPiecePrise(piece, dest, plateau);
        if (piecePrise != null) {
            boolean ok = arb.jouerPrise(piece, piecePrise, dest);
            if (ok) {
                SoundManager.playCapture();
                return true;
            }
        }

        // Sinon déplacement simple
        boolean ok = arb.jouerDeplacement(piece, dest);
        if (ok) {
            SoundManager.playMove();
        }
        return ok;
    }

    private void envoyerCoup(int lDep, int cDep, int lArr, int cArr) {
        if (coupCallback != null) {
            coupCallback.onCoup(lDep, cDep, lArr, cArr);
        }
    }

    /**
     * Après un coup validé : rafraîchir la grille DANS TOUS LES CAS,
     * gérer la chaîne de prises, et notifier le callback.
     */
    private void apresCoupe() {
        if (arb.isEnChaineDePrise()) {
            pieceSelectionnee = arb.getPieceEnChaine();
            calculerDestinations(pieceSelectionnee);
        } else {
            pieceSelectionnee = null;
            destinationsPossibles.clear();
        }

        // ★ FIX : toujours redessiner la grille après un coup
        redessinGrille();

        // Vérifier fin de partie
        if (arb.getGagnant() != null) {
            SoundManager.playVictory();
        }

        if (onCoupJoue != null) onCoupJoue.run();
    }
}

package org.example.leprojet.ui;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.effect.DropShadow;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.scene.paint.Color;
import javafx.scene.text.Font;
import javafx.scene.text.FontWeight;

/**
 * Menu d'accueil du jeu de dames.
 * <p>
 * Permet aux joueurs de saisir leur pseudo avant de commencer.
 * Fournit des boutons pour lancer la partie en mode local ou réseau.
 */
public class MenuView extends VBox {

    private final TextField pseudoField1;
    private final TextField pseudoField2;
    private final TextField hostField;
    private final TextField portField;
    private final Label lblStatus;
    private final Label lblPretBlanc;
    private final Label lblPretNoir;
    private final Label lblPretReseau;

    /** Callback pour le mode local (2 joueurs sur la même machine). */
    private OnLocalStart onLocalStart;

    /** Callback pour le mode réseau (connexion au serveur). */
    private OnNetworkStart onNetworkStart;

    // ── Interfaces de callback ─────────────────────────────────────────

    @FunctionalInterface
    public interface OnLocalStart {
        void start(String pseudoBlanc, String pseudoNoir);
    }

    @FunctionalInterface
    public interface OnNetworkStart {
        void start(String pseudo, String host, int port);
    }

    // ── Construction ───────────────────────────────────────────────────

    public MenuView() {
        getStyleClass().add("menu-root");
        setAlignment(Pos.CENTER);
        setSpacing(18);
        setPadding(new Insets(26));
        setStyle("-fx-background-color: linear-gradient(to bottom, #f6eee3, #dfd1bc);");
        setEffect(new DropShadow(16, Color.rgb(0, 0, 0, 0.20)));

        // Titre
        Label titre = new Label("♟ Jeu de Dames");
        titre.setFont(Font.font("System", FontWeight.BOLD, 28));
        titre.setStyle("-fx-text-fill: #3f2a1d;");

        Label sousTitre = new Label("Lobby - Reseau et local");
        sousTitre.setFont(Font.font("System", FontWeight.NORMAL, 14));
        sousTitre.setStyle("-fx-text-fill: #7b4b2a;");

        // ── Section : Partie locale ────────────────────────────────────

        Label lblLocal = creerSection("Partie locale (2 joueurs)");

        pseudoField1 = new TextField("Joueur Blanc");
        pseudoField1.setPromptText("Pseudo Joueur BLANC");
        pseudoField1.setMaxWidth(250);

        pseudoField2 = new TextField("Joueur Noir");
        pseudoField2.setPromptText("Pseudo Joueur NOIR");
        pseudoField2.setMaxWidth(250);

        lblPretBlanc = new Label();
        lblPretNoir = new Label();

        GridPane localGrid = new GridPane();
        localGrid.setHgap(8);
        localGrid.setVgap(8);
        localGrid.add(new Label("Blanc"), 0, 0);
        localGrid.add(pseudoField1, 1, 0);
        localGrid.add(lblPretBlanc, 2, 0);
        localGrid.add(new Label("Noir"), 0, 1);
        localGrid.add(pseudoField2, 1, 1);
        localGrid.add(lblPretNoir, 2, 1);

        Button btnLocal = creerBouton("▶  Jouer en local", "#4caf50");
        btnLocal.setOnAction(e -> onClickLocal());

        VBox localBox = new VBox(8, lblLocal, localGrid, btnLocal);
        localBox.getStyleClass().add("menu-card");
        localBox.setAlignment(Pos.CENTER);
        localBox.setPadding(new Insets(12));
        localBox.setStyle("-fx-background-color: rgba(255,255,255,0.55); -fx-background-radius: 12;");

        // ── Section : Partie réseau ────────────────────────────────────

        Label lblReseau = creerSection("Rejoindre un serveur");

        hostField = new TextField("127.0.0.1");
        hostField.setPromptText("Adresse du serveur");
        hostField.setMaxWidth(250);

        portField = new TextField("6000");
        portField.setPromptText("Port");
        portField.setMaxWidth(250);

        lblPretReseau = new Label();

        Button btnReseau = creerBouton("  Rejoindre", "#2196f3");
        btnReseau.setOnAction(e -> onClickReseau());

        GridPane reseauGrid = new GridPane();
        reseauGrid.setHgap(8);
        reseauGrid.setVgap(8);
        reseauGrid.add(new Label("Serveur"), 0, 0);
        reseauGrid.add(hostField, 1, 0);
        reseauGrid.add(new Label("Port"), 0, 1);
        reseauGrid.add(portField, 1, 1);
        reseauGrid.add(new Label("Statut"), 0, 2);
        reseauGrid.add(lblPretReseau, 1, 2);

        VBox reseauBox = new VBox(8, lblReseau, reseauGrid, btnReseau);
        reseauBox.getStyleClass().add("menu-card");
        reseauBox.setAlignment(Pos.CENTER);
        reseauBox.setPadding(new Insets(12));
        reseauBox.setStyle("-fx-background-color: rgba(255,255,255,0.55); -fx-background-radius: 12;");

        // ── Status ─────────────────────────────────────────────────────

        lblStatus = new Label("");
        lblStatus.setFont(Font.font("System", FontWeight.SEMI_BOLD, 12));
        lblStatus.setStyle("-fx-text-fill: #f44336;");

        // ── Assemblage ─────────────────────────────────────────────────

        HBox sections = new HBox(20, localBox, reseauBox);
        sections.setAlignment(Pos.CENTER);

        getChildren().addAll(titre, sousTitre, sections, lblStatus);

        pseudoField1.textProperty().addListener((obs, o, n) -> mettreAJourStatuts());
        pseudoField2.textProperty().addListener((obs, o, n) -> mettreAJourStatuts());
        hostField.textProperty().addListener((obs, o, n) -> mettreAJourStatuts());
        portField.textProperty().addListener((obs, o, n) -> mettreAJourStatuts());
        mettreAJourStatuts();
    }

    // ── Callbacks ──────────────────────────────────────────────────────

    public void setOnLocalStart(OnLocalStart cb)     { this.onLocalStart = cb; }
    public void setOnNetworkStart(OnNetworkStart cb) { this.onNetworkStart = cb; }

    // ── Actions ────────────────────────────────────────────────────────

    private void onClickLocal() {
        String p1 = pseudoField1.getText().isBlank() ? "Joueur Blanc" : pseudoField1.getText().trim();
        String p2 = pseudoField2.getText().isBlank() ? "Joueur Noir" : pseudoField2.getText().trim();
        lblStatus.setText("");
        if (onLocalStart != null) {
            onLocalStart.start(p1, p2);
        }
    }

    private void onClickReseau() {
        String host = hostField.getText().isBlank() ? "127.0.0.1" : hostField.getText().trim();
        int port;
        try {
            port = Integer.parseInt(portField.getText().trim());
        } catch (NumberFormatException e) {
            lblStatus.setText("⚠ Port invalide !");
            return;
        }
        String pseudo = pseudoField1.getText().isBlank() ? "Joueur" : pseudoField1.getText().trim();
        lblStatus.setText("");
        if (onNetworkStart != null) {
            onNetworkStart.start(pseudo, host, port);
        }
    }

    // ── Utilitaires visuels ────────────────────────────────────────────

    private Label creerSection(String texte) {
        Label l = new Label(texte);
        l.setFont(Font.font("System", FontWeight.BOLD, 15));
        l.setStyle("-fx-text-fill: #3f2a1d;");
        return l;
    }

    private Button creerBouton(String texte, String couleur) {
        Button btn = new Button(texte);
        btn.setStyle("-fx-font-size: 13; -fx-padding: 8 20; "
                + "-fx-background-color: " + couleur + "; -fx-text-fill: white; "
                + "-fx-background-radius: 8; -fx-cursor: hand;");
        return btn;
    }

    private void mettreAJourStatuts() {
        boolean blancOk = !pseudoField1.getText().isBlank();
        boolean noirOk = !pseudoField2.getText().isBlank();
        boolean hostOk = !hostField.getText().isBlank();
        boolean portOk;
        try {
            int port = Integer.parseInt(portField.getText().trim());
            portOk = port > 0 && port <= 65535;
        } catch (Exception e) {
            portOk = false;
        }

        setPretLabel(lblPretBlanc, blancOk);
        setPretLabel(lblPretNoir, noirOk);
        setPretLabel(lblPretReseau, hostOk && portOk);
    }

    private void setPretLabel(Label lbl, boolean pret) {
        if (pret) {
            lbl.setText("Pret");
            lbl.setStyle("-fx-text-fill: #2e7d32; -fx-font-weight: bold;");
        } else {
            lbl.setText("En attente");
            lbl.setStyle("-fx-text-fill: #c62828; -fx-font-weight: bold;");
        }
    }
}

package org.example.leprojet.ui;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.effect.DropShadow;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.scene.paint.Color;
import javafx.scene.text.Font;
import javafx.scene.text.FontWeight;

/**
 * Menu d'accueil du jeu de dames.
 * <p>
 * Permet aux joueurs de saisir leur pseudo avant de commencer.
 * Fournit des boutons pour lancer la partie en mode local ou réseau.
 */
public class MenuView extends VBox {

    private final TextField pseudoField1;
    private final TextField pseudoField2;
    private final TextField pseudoReseauField;
    private final TextField hostField;
    private final TextField portField;
    private final Label lblStatus;
    private final Label lblPretBlanc;
    private final Label lblPretNoir;
    private final Label lblPretReseau;

    /** Callback pour le mode local (2 joueurs sur la même machine). */
    private OnLocalStart onLocalStart;

    /** Callback pour le mode réseau (connexion au serveur). */
    private OnNetworkStart onNetworkStart;

    // ── Interfaces de callback ─────────────────────────────────────────

    @FunctionalInterface
    public interface OnLocalStart {
        void start(String pseudoBlanc, String pseudoNoir);
    }

    @FunctionalInterface
    public interface OnNetworkStart {
        void start(String pseudo, String host, int port);
    }

    // ── Construction ───────────────────────────────────────────────────

    public MenuView() {
        getStyleClass().add("menu-root");
        setAlignment(Pos.CENTER);
        setSpacing(18);
        setPadding(new Insets(26));
        setStyle("-fx-background-color: linear-gradient(to bottom, #f6eee3, #dfd1bc);");
        setEffect(new DropShadow(16, Color.rgb(0, 0, 0, 0.20)));

        // Titre
        Label titre = new Label("♟ Jeu de Dames");
        titre.setFont(Font.font("System", FontWeight.BOLD, 28));
        titre.setStyle("-fx-text-fill: #3f2a1d;");

        Label sousTitre = new Label("Lobby - Reseau et local");
        sousTitre.setFont(Font.font("System", FontWeight.NORMAL, 14));
        sousTitre.setStyle("-fx-text-fill: #7b4b2a;");

        // ── Section : Partie locale ────────────────────────────────────

        Label lblLocal = creerSection("Partie locale (2 joueurs)");

        pseudoField1 = new TextField("Joueur Blanc");
        pseudoField1.setPromptText("Pseudo Joueur BLANC");
        pseudoField1.setMaxWidth(250);

        pseudoField2 = new TextField("Joueur Noir");
        pseudoField2.setPromptText("Pseudo Joueur NOIR");
        pseudoField2.setMaxWidth(250);

        lblPretBlanc = new Label();
        lblPretNoir = new Label();

        GridPane localGrid = new GridPane();
        localGrid.setHgap(8);
        localGrid.setVgap(8);
        localGrid.add(new Label("Blanc"), 0, 0);
        localGrid.add(pseudoField1, 1, 0);
        localGrid.add(lblPretBlanc, 2, 0);
        localGrid.add(new Label("Noir"), 0, 1);
        localGrid.add(pseudoField2, 1, 1);
        localGrid.add(lblPretNoir, 2, 1);

        Button btnLocal = creerBouton("▶  Jouer en local", "#4caf50");
        btnLocal.setOnAction(e -> onClickLocal());

        VBox localBox = new VBox(8, lblLocal, localGrid, btnLocal);
        localBox.getStyleClass().add("menu-card");
        localBox.setAlignment(Pos.CENTER);
        localBox.setPadding(new Insets(12));
        localBox.setStyle("-fx-background-color: rgba(255,255,255,0.55); -fx-background-radius: 12;");

        // ── Section : Partie réseau ────────────────────────────────────

        Label lblReseau = creerSection("Rejoindre un serveur");

        pseudoReseauField = new TextField("Joueur");
        pseudoReseauField.setPromptText("Pseudo réseau");
        pseudoReseauField.setMaxWidth(250);

        hostField = new TextField("127.0.0.1");
        hostField.setPromptText("Adresse du serveur");
        hostField.setMaxWidth(250);

        portField = new TextField("6000");
        portField.setPromptText("Port");
        portField.setMaxWidth(250);

        lblPretReseau = new Label();

        Button btnReseau = creerBouton("  Rejoindre", "#2196f3");
        btnReseau.setOnAction(e -> onClickReseau());

        GridPane reseauGrid = new GridPane();
        reseauGrid.setHgap(8);
        reseauGrid.setVgap(8);
        reseauGrid.add(new Label("Pseudo"), 0, 0);
        reseauGrid.add(pseudoReseauField, 1, 0);
        reseauGrid.add(new Label("Serveur"), 0, 1);
        reseauGrid.add(hostField, 1, 1);
        reseauGrid.add(new Label("Port"), 0, 2);
        reseauGrid.add(portField, 1, 2);
        reseauGrid.add(new Label("Statut"), 0, 3);
        reseauGrid.add(lblPretReseau, 1, 3);

        VBox reseauBox = new VBox(8, lblReseau, reseauGrid, btnReseau);
        reseauBox.getStyleClass().add("menu-card");
        reseauBox.setAlignment(Pos.CENTER);
        reseauBox.setPadding(new Insets(12));
        reseauBox.setStyle("-fx-background-color: rgba(255,255,255,0.55); -fx-background-radius: 12;");

        // ── Status ─────────────────────────────────────────────────────

        lblStatus = new Label("");
        lblStatus.setFont(Font.font("System", FontWeight.SEMI_BOLD, 12));
        lblStatus.setStyle("-fx-text-fill: #f44336;");

        // ── Assemblage ─────────────────────────────────────────────────

        HBox sections = new HBox(20, localBox, reseauBox);
        sections.setAlignment(Pos.CENTER);

        getChildren().addAll(titre, sousTitre, sections, lblStatus);

        pseudoField1.textProperty().addListener((obs, o, n) -> mettreAJourStatuts());
        pseudoField2.textProperty().addListener((obs, o, n) -> mettreAJourStatuts());
        pseudoReseauField.textProperty().addListener((obs, o, n) -> mettreAJourStatuts());
        hostField.textProperty().addListener((obs, o, n) -> mettreAJourStatuts());
        portField.textProperty().addListener((obs, o, n) -> mettreAJourStatuts());
        mettreAJourStatuts();
    }

    // ── Callbacks ──────────────────────────────────────────────────────

    public void setOnLocalStart(OnLocalStart cb)     { this.onLocalStart = cb; }
    public void setOnNetworkStart(OnNetworkStart cb) { this.onNetworkStart = cb; }

    // ── Actions ────────────────────────────────────────────────────────

    private void onClickLocal() {
        String p1 = pseudoField1.getText().isBlank() ? "Joueur Blanc" : pseudoField1.getText().trim();
        String p2 = pseudoField2.getText().isBlank() ? "Joueur Noir" : pseudoField2.getText().trim();
        lblStatus.setText("");
        if (onLocalStart != null) {
            onLocalStart.start(p1, p2);
        }
    }

    private void onClickReseau() {
        String host = hostField.getText().isBlank() ? "127.0.0.1" : hostField.getText().trim();
        int port;
        try {
            port = Integer.parseInt(portField.getText().trim());
        } catch (NumberFormatException e) {
            lblStatus.setText("⚠ Port invalide !");
            return;
        }
        String pseudo = pseudoReseauField.getText() == null ? "" : pseudoReseauField.getText().trim();
        if (pseudo.isBlank()) {
            lblStatus.setText("⚠ Pseudo requis pour le mode réseau.");
            return;
        }
        lblStatus.setText("");
        if (onNetworkStart != null) {
            onNetworkStart.start(pseudo, host, port);
        }
    }

    // ── Utilitaires visuels ────────────────────────────────────────────

    private Label creerSection(String texte) {
        Label l = new Label(texte);
        l.setFont(Font.font("System", FontWeight.BOLD, 15));
        l.setStyle("-fx-text-fill: #3f2a1d;");
        return l;
    }

    private Button creerBouton(String texte, String couleur) {
        Button btn = new Button(texte);
        btn.setStyle("-fx-font-size: 13; -fx-padding: 8 20; "
                + "-fx-background-color: " + couleur + "; -fx-text-fill: white; "
                + "-fx-background-radius: 8; -fx-cursor: hand;");
        return btn;
    }

    private void mettreAJourStatuts() {
        boolean blancOk = !pseudoField1.getText().isBlank();
        boolean noirOk = !pseudoField2.getText().isBlank();
        boolean pseudoReseauOk = pseudoReseauField.getText() != null && !pseudoReseauField.getText().isBlank();
        boolean hostOk = !hostField.getText().isBlank();
        boolean portOk;
        try {
            int port = Integer.parseInt(portField.getText().trim());
            portOk = port > 0 && port <= 65535;
        } catch (Exception e) {
            portOk = false;
        }

        setPretLabel(lblPretBlanc, blancOk);
        setPretLabel(lblPretNoir, noirOk);
        setPretLabel(lblPretReseau, pseudoReseauOk && hostOk && portOk);
    }

    private void setPretLabel(Label lbl, boolean pret) {
        if (pret) {
            lbl.setText("Pret");
            lbl.setStyle("-fx-text-fill: #2e7d32; -fx-font-weight: bold;");
        } else {
            lbl.setText("En attente");
            lbl.setStyle("-fx-text-fill: #c62828; -fx-font-weight: bold;");
        }
    }
}

package org.example.leprojet.ui;

import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.Clip;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.LineEvent;
import java.io.ByteArrayInputStream;
import java.util.Random;

/**
 * Gestionnaire d'effets sonores pour le jeu de dames.
 * <p>
 * Génère des sons synthétiques imitant le style chess.com :
 * <ul>
 *   <li><b>Move</b> : claquement sec de pièce posée sur bois ("toc")</li>
 *   <li><b>Capture</b> : impact sourd + crack ("TOCK")</li>
 *   <li><b>Promotion</b> : son ascendant brillant</li>
 *   <li><b>Victory</b> : fanfare courte</li>
 * </ul>
 */
public class SoundManager {

    private static boolean enabled = true;
    private static final float SAMPLE_RATE = 44100f;
    private static final Random RNG = new Random();

    private SoundManager() {
    }

    public static void setEnabled(boolean enabled) {
        SoundManager.enabled = enabled;
    }

    public static boolean isEnabled() {
        return enabled;
    }

    // ── Sons publics ───────────────────────────────────────────────────

    /**
     * "Toc" court et sec — pièce posée sur le damier (style chess.com move).
     */
    public static void playMove() {
        playAsync(() -> jouerSon(genererSonMove()));
    }

    /**
     * Impact sourd + crack — pièce capturée (style chess.com capture).
     */
    public static void playCapture() {
        playAsync(() -> jouerSon(genererSonCapture()));
    }

    /**
     * Son ascendant brillant — promotion en dame.
     */
    public static void playPromotion() {
        playAsync(() -> jouerSon(genererSonPromotion()));
    }

    /**
     * Fanfare courte — victoire.
     */
    public static void playVictory() {
        playAsync(() -> jouerSon(genererSonVictory()));
    }

    // ── Génération : Move ("toc" bois) ─────────────────────────────────

    private static byte[] genererSonMove() {
        int durée = ms(75);
        byte[] buf = new byte[durée];

        for (int i = 0; i < durée; i++) {
            double t = i / SAMPLE_RATE;
            // "Toc" : bruit filtré + tonale basse, decay exponentiel rapide
            double decay = Math.exp(-t * 80);
            double tonale = Math.sin(2 * Math.PI * 1200 * t) * 0.4;
            double bruit = (RNG.nextDouble() * 2 - 1) * 0.6;
            // Filtre passe-bas simplifié sur le bruit
            double signal = (tonale + bruit * decay * 0.5) * decay;
            buf[i] = clamp(signal * 110);
        }
        return buf;
    }

    // ── Génération : Capture ("TOCK" grave + crack) ────────────────────

    private static byte[] genererSonCapture() {
        int durée = ms(130);
        byte[] buf = new byte[durée];

        for (int i = 0; i < durée; i++) {
            double t = i / SAMPLE_RATE;

            // Phase 1 : impact grave "THUD" (0-40ms)
            double decayImpact = Math.exp(-t * 50);
            double thud = Math.sin(2 * Math.PI * 200 * t) * decayImpact * 0.6;

            // Phase 2 : crack bois aigü (0-20ms)
            double decayCrack = Math.exp(-t * 150);
            double crack = (RNG.nextDouble() * 2 - 1) * decayCrack * 0.5;

            // Phase 3 : tonale médium
            double decayTone = Math.exp(-t * 60);
            double tone = Math.sin(2 * Math.PI * 800 * t) * decayTone * 0.3;

            double signal = thud + crack + tone;
            buf[i] = clamp(signal * 120);
        }
        return buf;
    }

    // ── Génération : Promotion (arpège ascendant) ──────────────────────

    private static byte[] genererSonPromotion() {
        int durée = ms(280);
        byte[] buf = new byte[durée];

        double[] notes = {523.25, 659.25, 783.99, 1046.50}; // C5, E5, G5, C6
        int noteDurée = durée / notes.length;

        for (int i = 0; i < durée; i++) {
            int noteIdx = Math.min(i / noteDurée, notes.length - 1);
            double freq = notes[noteIdx];
            double t = i / SAMPLE_RATE;
            double localT = (i - noteIdx * noteDurée) / SAMPLE_RATE;
            double envelope = Math.exp(-localT * 12) * Math.min(localT * 500, 1.0);

            double signal = Math.sin(2 * Math.PI * freq * t) * envelope;
            // Ajouter harmonique douce
            signal += Math.sin(2 * Math.PI * freq * 2 * t) * envelope * 0.2;
            buf[i] = clamp(signal * 80);
        }
        return buf;
    }

    // ── Génération : Victory (fanfare) ─────────────────────────────────

    private static byte[] genererSonVictory() {
        int durée = ms(500);
        byte[] buf = new byte[durée];

        // Trois accords joyeux successifs
        double[][] accords = {
                {523.25, 659.25, 783.99},  // C maj
                {587.33, 739.99, 880.00},  // D maj
                {659.25, 830.61, 987.77},  // E maj
        };
        int accordDurée = durée / accords.length;

        for (int i = 0; i < durée; i++) {
            int accIdx = Math.min(i / accordDurée, accords.length - 1);
            double localT = (i - accIdx * accordDurée) / SAMPLE_RATE;
            double envelope = Math.exp(-localT * 5) * Math.min(localT * 300, 1.0);

            double signal = 0;
            for (double freq : accords[accIdx]) {
                double t = i / SAMPLE_RATE;
                signal += Math.sin(2 * Math.PI * freq * t) * envelope;
            }
            signal /= accords[accIdx].length;
            buf[i] = clamp(signal * 80);
        }
        return buf;
    }

    // ── Lecture audio ──────────────────────────────────────────────────

    private static void jouerSon(byte[] samples) {
        try {
            AudioFormat format = new AudioFormat(SAMPLE_RATE, 8, 1, true, false);
            AudioInputStream ais = new AudioInputStream(
                    new ByteArrayInputStream(samples), format, samples.length);

            Clip clip = AudioSystem.getClip();
            clip.open(ais);
            clip.start();
            clip.addLineListener(event -> {
                if (event.getType() == LineEvent.Type.STOP) {
                    clip.close();
                }
            });
        } catch (Exception e) {
            // Son non critique
        }
    }

    private static void playAsync(Runnable task) {
        if (!enabled) return;
        Thread t = new Thread(task, "sound");
        t.setDaemon(true);
        t.start();
    }

    // ── Utilitaires ────────────────────────────────────────────────────

    /** Convertit des millisecondes en nombre d'échantillons. */
    private static int ms(int milliseconds) {
        return (int) (SAMPLE_RATE * milliseconds / 1000);
    }

    /** Clamp un double en byte signé [-128, 127]. */
    private static byte clamp(double value) {
        return (byte) Math.max(-127, Math.min(127, (int) value));
    }
}

package org.example.leprojet.ui;

import javafx.scene.media.AudioClip;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.EnumMap;
import java.util.Map;
import java.util.Random;

/**
 * Gestionnaire d'effets sonores pour le jeu de dames.
 * <p>
 * Génère des sons synthétiques imitant le style chess.com :
 * <ul>
 *   <li><b>Move</b> : claquement sec de pièce posée sur bois ("toc")</li>
 *   <li><b>Capture</b> : impact sourd + crack ("TOCK")</li>
 *   <li><b>Promotion</b> : son ascendant brillant</li>
 *   <li><b>Victory</b> : fanfare courte</li>
 * </ul>
 */
public class SoundManager {

    private enum SoundId {
        MOVE,
        CAPTURE,
        ENDGAME
    }

    private static boolean enabled = true;
    private static final float SAMPLE_RATE = 44100f;
    private static final double MASTER_GAIN = 0.72;
    private static final Random RNG = new Random();
    private static final Map<SoundId, AudioClip> CLIPS = new EnumMap<>(SoundId.class);
    private static final Map<SoundId, Path> TEMP_FILES = new EnumMap<>(SoundId.class);
    private static volatile boolean initialized;

    private SoundManager() {
    }

    public static void setEnabled(boolean enabled) {
        SoundManager.enabled = enabled;
    }

    public static boolean isEnabled() {
        return enabled;
    }

    // ── Sons publics ───────────────────────────────────────────────────

    /**
     * "Toc" court et sec — pièce posée sur le damier (style chess.com move).
     */
    public static void playMove() {
        play(SoundId.MOVE);
    }

    /**
     * Impact sourd + crack — pièce capturée (style chess.com capture).
     */
    public static void playCapture() {
        play(SoundId.CAPTURE);
    }

    /**
     * Son ascendant brillant — promotion en dame.
     */
    public static void playPromotion() {
        play(SoundId.MOVE);
    }

    /**
     * Fanfare courte — victoire.
     */
    public static void playVictory() {
        play(SoundId.ENDGAME);
    }

    /** Son de fin de partie, appelé à l'arrêt d'une session réseau/local. */
    public static void playEndgame() {
        play(SoundId.ENDGAME);
    }

    // ── Génération : Move ("toc" bois) ─────────────────────────────────

    private static byte[] genererSonMove() {
        int durée = ms(75);
        byte[] buf = new byte[durée];

        for (int i = 0; i < durée; i++) {
            double t = i / SAMPLE_RATE;
            // "Toc" : bruit filtré + tonale basse, decay exponentiel rapide
            double decay = Math.exp(-t * 78);
            double tonale = Math.sin(2 * Math.PI * 980 * t) * 0.34;
            double bruit = (RNG.nextDouble() * 2 - 1) * 0.48;
            // Filtre passe-bas simplifié sur le bruit
            double signal = (tonale + bruit * decay * 0.5) * decay;
            buf[i] = clamp(signal * 88);
        }
        return buf;
    }

    // ── Génération : Capture ("TOCK" grave + crack) ────────────────────

    private static byte[] genererSonCapture() {
        int durée = ms(130);
        byte[] buf = new byte[durée];

        for (int i = 0; i < durée; i++) {
            double t = i / SAMPLE_RATE;

            // Phase 1 : impact grave "THUD" (0-40ms)
            double decayImpact = Math.exp(-t * 45);
            double thud = Math.sin(2 * Math.PI * 190 * t) * decayImpact * 0.55;

            // Phase 2 : crack bois aigü (0-20ms)
            double decayCrack = Math.exp(-t * 140);
            double crack = (RNG.nextDouble() * 2 - 1) * decayCrack * 0.35;

            // Phase 3 : tonale médium
            double decayTone = Math.exp(-t * 58);
            double tone = Math.sin(2 * Math.PI * 740 * t) * decayTone * 0.24;

            double signal = thud + crack + tone;
            buf[i] = clamp(signal * 92);
        }
        return buf;
    }

    // ── Génération : Promotion (arpège ascendant) ──────────────────────

    private static byte[] genererSonVictory() {
        int durée = ms(420);
        byte[] buf = new byte[durée];

        // Son sec de "fin" : attaque courte + résonance discrète.
        double hitFreq = 640;
        double bodyFreq = 280;

        for (int i = 0; i < durée; i++) {
            double t = i / SAMPLE_RATE;
            double hitEnv = Math.exp(-t * 42);
            double bodyEnv = Math.exp(-t * 9);
            double hit = Math.sin(2 * Math.PI * hitFreq * t) * hitEnv * 0.65;
            double body = Math.sin(2 * Math.PI * bodyFreq * t) * bodyEnv * 0.35;
            double noise = (RNG.nextDouble() * 2 - 1) * Math.exp(-t * 80) * 0.18;
            buf[i] = clamp((hit + body + noise) * 86);
        }
        return buf;
    }

    private static void play(SoundId soundId) {
        if (!enabled) return;
        ensureInitialized();
        AudioClip clip = CLIPS.get(soundId);
        if (clip == null) return;
        clip.stop();
        clip.play(MASTER_GAIN);
    }

    private static synchronized void ensureInitialized() {
        if (initialized) return;
        try {
            chargerClip(SoundId.MOVE, genererSonMove());
            chargerClip(SoundId.CAPTURE, genererSonCapture());
            chargerClip(SoundId.ENDGAME, genererSonVictory());
            initialized = true;
        } catch (Exception e) {
            // Son non critique
        }
    }

    private static void chargerClip(SoundId id, byte[] samples) throws IOException {
        byte[] wav = buildWav(samples, (int) SAMPLE_RATE);
        Path tempWav = Files.createTempFile("leprojet-sound-" + id.name().toLowerCase() + "-", ".wav");
        Files.write(tempWav, wav, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING);
        tempWav.toFile().deleteOnExit();

        AudioClip clip = new AudioClip(tempWav.toUri().toString());
        clip.setCycleCount(1);
        CLIPS.put(id, clip);
        TEMP_FILES.put(id, tempWav);
    }

    public static synchronized void shutdown() {
        for (AudioClip clip : CLIPS.values()) {
            clip.stop();
        }
        CLIPS.clear();

        for (Path p : TEMP_FILES.values()) {
            try {
                Files.deleteIfExists(p);
            } catch (IOException ignored) {
            }
        }
        TEMP_FILES.clear();
        initialized = false;
    }

    private static byte[] buildWav(byte[] pcm8bit, int sampleRate) {
        int dataSize = pcm8bit.length;
        int fileSizeMinus8 = 36 + dataSize;

        byte[] wav = new byte[44 + dataSize];
        int idx = 0;
        idx = putAscii(wav, idx, "RIFF");
        idx = putLeInt(wav, idx, fileSizeMinus8);
        idx = putAscii(wav, idx, "WAVE");
        idx = putAscii(wav, idx, "fmt ");
        idx = putLeInt(wav, idx, 16);
        idx = putLeShort(wav, idx, 1);
        idx = putLeShort(wav, idx, 1);
        idx = putLeInt(wav, idx, sampleRate);
        idx = putLeInt(wav, idx, sampleRate);
        idx = putLeShort(wav, idx, 1);
        idx = putLeShort(wav, idx, 8);
        idx = putAscii(wav, idx, "data");
        idx = putLeInt(wav, idx, dataSize);

        // WAV PCM 8-bit doit être non signé : conversion [-128..127] -> [0..255].
        for (int i = 0; i < dataSize; i++) {
            int signed = pcm8bit[i];
            wav[idx + i] = (byte) (signed + 128);
        }
        return wav;
    }

    private static int putAscii(byte[] out, int offset, String s) {
        for (int i = 0; i < s.length(); i++) {
            out[offset + i] = (byte) s.charAt(i);
        }
        return offset + s.length();
    }

    private static int putLeInt(byte[] out, int offset, int value) {
        out[offset] = (byte) (value & 0xff);
        out[offset + 1] = (byte) ((value >>> 8) & 0xff);
        out[offset + 2] = (byte) ((value >>> 16) & 0xff);
        out[offset + 3] = (byte) ((value >>> 24) & 0xff);
        return offset + 4;
    }

    private static int putLeShort(byte[] out, int offset, int value) {
        out[offset] = (byte) (value & 0xff);
        out[offset + 1] = (byte) ((value >>> 8) & 0xff);
        return offset + 2;
    }

    // ── Utilitaires ────────────────────────────────────────────────────

    /** Convertit des millisecondes en nombre d'échantillons. */
    private static int ms(int milliseconds) {
        return (int) (SAMPLE_RATE * milliseconds / 1000);
    }

    /** Clamp un double en byte signé [-128, 127]. */
    private static byte clamp(double value) {
        return (byte) Math.max(-127, Math.min(127, (int) value));
    }
}

